import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // null for accounts that only ever signed in via an OAuth provider (Google).
  passwordHash: string | null;
};

const users: User[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    passwordHash: null,
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    passwordHash: null,
  },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function findUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

// Creates an email/password account. `password` is omitted for OAuth-provisioned users.
export async function createUser(params: {
  email: string;
  name: string;
  password?: string;
}): Promise<User> {
  const email = params.email.trim().toLowerCase();
  if (await findUserByEmail(email)) {
    throw new Error("A user with that email already exists.");
  }

  const user: User = {
    id: String(nextId++),
    email,
    name: params.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: params.password ? await bcrypt.hash(params.password, 10) : null,
  };
  users.push(user);
  return user;
}

// Used by the credentials provider to check a login attempt against the store.
